import {partDefaults} from './part-parameters.js';
export const EXTRA_SENSOR_EXAMPLES=[{id:'ina219',name:'Uno · INA219 şönt ölçümü',tag:'12 V / 100 Ω · gerçek0.1 Ω'},{id:'max6675',name:'Uno · MAX6675 termokupl',tag:'K · SPI / open / conversion'}];
export const EXTRA_SENSOR_SOURCES={ina219:`#include <Wire.h>
void writeReg(uint8_t a,uint16_t v){Wire.beginTransmission(0x40);Wire.write(a);Wire.write(v>>8);Wire.write(v);Wire.endTransmission();}
uint16_t readReg(uint8_t a){Wire.beginTransmission(0x40);Wire.write(a);Wire.endTransmission(false);Wire.requestFrom(0x40,2);uint16_t v=Wire.read();return (v<<8)|Wire.read();}
void setup(){Serial.begin(115200);Wire.begin();writeReg(5,4096);writeReg(0,0x399f);}
void loop(){uint16_t bus=readReg(2);int16_t shunt=readReg(1),current=readReg(4);uint16_t power=readReg(3);Serial.print("INA BUS_mV=");Serial.print((bus>>3)*4);Serial.print(" SHUNT_uV=");Serial.print((long)shunt*10);Serial.print(" I_100uA=");Serial.print(current);Serial.print(" P_2mW=");Serial.print(power);Serial.print(" FLAGS=");Serial.println(bus&7);delay(100);}
`,max6675:`#include <SPI.h>
void setup(){Serial.begin(115200);pinMode(10,OUTPUT);digitalWrite(10,HIGH);SPI.begin();SPI.beginTransaction(SPISettings(1000000,MSBFIRST,SPI_MODE0));}
void loop(){delay(250);digitalWrite(10,LOW);uint16_t v=SPI.transfer(0);v=(v<<8)|SPI.transfer(0);digitalWrite(10,HIGH);Serial.print("MAX6675 ");if(v&4)Serial.println("OPEN");else{Serial.print((v>>3)*0.25);Serial.println(" C");}}
`};
export function makeExtraSensorProject(base,id){const e=EXTRA_SENSOR_EXAMPLES.find(e=>e.id===id);if(!e)return null;const p=structuredClone(base);p.model=id;p.name=e.name;p.code=EXTRA_SENSOR_SOURCES[id];delete p.firmware;const part=(type,id,params={},x=740,y=400)=>p.components.push({id,type,x,y,rotation:0,params:{...partDefaults(type),...params}}),wire=(from,to,color='#14b8a6')=>p.wires.push({id:'extra'+p.wires.length,from,to,color,points:[]});part(id,'module');wire('uno:5V','module:VCC','#ef4444');wire('uno:GND.1','module:GND','#64748b');
 if(id==='ina219'){wire('uno:A4','module:SDA');wire('uno:A5','module:SCL');for(const pin of['A0','A1'])wire('uno:GND.1','module:'+pin,'#64748b');part('resistor','sda',{ohms:4700},525,500);part('resistor','scl',{ohms:4700},525,550);wire('uno:5V','sda:1','#ef4444');wire('sda:2','module:SDA');wire('uno:5V','scl:1','#ef4444');wire('scl:2','module:SCL');part('supply','source',{voltage:12},955,215);part('resistor','shunt',{ohms:.1},805,265);part('resistor','load',{ohms:100},955,440);wire('source:GND','uno:GND.1','#64748b');wire('source:VCC','shunt:1','#ef4444');wire('shunt:2','load:1','#ef4444');wire('load:2','source:GND','#64748b');wire('shunt:1','module:VIN+','#f59e0b');wire('shunt:2','module:VIN-','#f59e0b');p.settings.measurement={positive:'shunt:1',negative:'shunt:2',current:'load:i'};p.settings.scopeMode='dc';p.settings.probe='A4';}
 else{for(const[a,b]of[['D13','SCK'],['D10','CS'],['D12','SO'],['GND.1','T-']])wire('uno:'+a,'module:'+b);p.settings.probe='D13';p.settings.tracePins=['D10','D12'];}return p;}
